struct Scope {
    std::unordered_map<std::string_view, Symbol> syms;
    Scope* parent;
    bool define(std::string_view n, Symbol s) { return syms.emplace(n, s).second; }  // dup -> false
    const Symbol* lookup(std::string_view n) {                                        // inner -> outer
        for (Scope* s = this; s; s = s->parent)
            if (auto it = s->syms.find(n); it != s->syms.end()) return &it->second;
        return nullptr;
    }
};
